import { cwd } from "../../src/platform/index.js";
import { parseArgsOrThrow } from "./args.js";
import { showHeader } from "../utils/index.js";
export async function handleProjectDirCommand(args, parser, commandName, command) {
    showHeader();
    const data = parseArgsOrThrow(parser, commandName, args);
    await command({ ...data, projectDir: data.projectDir || cwd() });
}
